<?phpuse Illuminate\Support\Facades\Route;use App\Http\Controllers\DonaturController;use App\Http\Controllers\DonasiController;use App\Http\Controllers\AuthController;use App\Http\Controllers\UserController;use App\Http\Controllers\AdminDonasiController;Route::post('/register', [AuthController::class, 'register']);Route::post('/register-admin', [AuthController::class, 'registerAdmin']);Route::post('/login', [AuthController::class, 'login']);Route::post('/logout', [AuthController::class, 'logout'])->middleware('auth:sanctum');Route::post('/donatur', [DonaturController::class, 'store']); // anonimRoute::post('/donasi/public', [DonasiController::class, 'storePublic']);Route::middleware(['auth:sanctum', 'role:admin'])->group(function (){ Route::get('/admin/dashboard', function (){ return response()->json(['message'=>'Welcome Admin Dashboard']);}); // Buat admin / petugas Route::post('/create-admin', [UserController::class, 'createAdmin']); Route::post('/create-petugas', [UserController::class, 'createPetugas']); // CRUD Donatur Route::post('/donatur', [DonaturController::class, 'store']); Route::put('/donatur/{donatur}', [DonaturController::class, 'update']); Route::delete('/donatur/{donatur}', [DonaturController::class, 'destroy']); // CRUD Donasi Route::post('/donasi', [DonasiController::class, 'store']); Route::put('/donasi/{donasi}', [DonasiController::class, 'update']); Route::delete('/donasi/{donasi}', [DonasiController::class, 'destroy']); // Verifikasi donasi Route::put('/donasi/{id}/verifikasi', [DonasiController::class, 'verifikasiAdmin']); // Admin Donasi Dashboard Route::get('/admin/donasi', [AdminDonasiController::class, 'index']); Route::get('/admin/dashboard-data', [AdminDonasiController::class, 'dashboard']); Route::post('/admin/donasi/verifikasi', [AdminDonasiController::class, 'updateVerifikasi'])});Route::middleware(['auth:sanctum', 'role:petugas'])->group(function (){ Route::get('/petugas/dashboard', function (){ return response()->json(['message'=>'Welcome Petugas Dashboard']);}); Route::post('/petugas/update-bantuan', [DonasiController::class, 'updateStatusByPetugas']); Route::get('/petugas/dashboard-data', [DonasiController::class, 'dashboardPetugas']); Route::get('/petugas/pelacakan', [DonasiController::class, 'pelacakanPetugas']); Route::get('/petugas/laporan', [DonasiController::class, 'laporanPetugas'])});Route::middleware(['auth:sanctum', 'role:user'])->group(function (){ Route::get('/user/dashboard', function (){ return response()->json(['message'=>'Welcome User Dashboard']);}); Route::get('/user/profile', [UserController::class, 'profile']); Route::post('/user/profile', [UserController::class, 'updateProfile']); Route::delete('/user/profile/photo', [UserController::class, 'deletePhoto']); Route::get('/donasi/user', [DonasiController::class, 'donasiUser'])});Route::middleware('auth:sanctum')->group(function (){ // Donatur Route::get('/donatur', [DonaturController::class, 'index']); Route::get('/donatur/{donatur}', [DonaturController::class, 'show']); // Donasi Route::get('/donasi', [DonasiController::class, 'index']); Route::get('/donasi/{donasi}', [DonasiController::class, 'show']); // Laporan Route::get('/laporan', [DonasiController::class, 'laporan']); Route::get('/laporan-pdf', [DonasiController::class, 'laporanPdf'])});Route::middleware(['auth:sanctum', 'role:admin,petugas'])->group(function (){ Route::get('/donasi', [DonasiController::class, 'index'])});